CREATE VIEW v_customer_consumption AS SELECT customers.CustomerID AS customer_id, customers.Segment AS customer_segment, customers.Currency AS currency, yearmonth.Date AS year_month, yearmonth.Consumption AS consumption, yearmonth.CustomerID FROM customers LEFT JOIN yearmonth ON customers.CustomerID = yearmonth.CustomerID;

CREATE VIEW v_transaction_details AS SELECT transactions_1k.TransactionID AS transaction_id, transactions_1k.Date AS transaction_date, transactions_1k.Time AS transaction_time, transactions_1k.CustomerID AS customer_id, transactions_1k.CardID AS card_id, transactions_1k.GasStationID AS gas_station_id, transactions_1k.ProductID AS product_id, transactions_1k.Amount AS amount, transactions_1k.Price AS price, gasstations.Country AS station_country, gasstations.Segment AS station_segment, gasstations.ChainID AS station_chain_id, products.Description AS product_description, gasstations.GasStationID, products.ProductID FROM transactions_1k LEFT JOIN gasstations ON transactions_1k.GasStationID = gasstations.GasStationID LEFT JOIN products ON transactions_1k.ProductID = products.ProductID;

CREATE VIEW v_customers_gasstations_transactions_1k AS SELECT customers.CustomerID, customers.Segment, customers.Currency, transactions_1k.TransactionID, transactions_1k.Date, transactions_1k.Time, transactions_1k.CustomerID AS transactions_1k_CustomerID, transactions_1k.GasStationID, transactions_1k.ProductID, transactions_1k.Amount, transactions_1k.Price, gasstations.GasStationID AS gasstations_GasStationID, gasstations.ChainID, gasstations.Country, gasstations.Segment AS gasstations_Segment FROM customers INNER JOIN transactions_1k ON customers.customerid = transactions_1k.customerid INNER JOIN gasstations ON transactions_1k.gasstationid = gasstations.gasstationid;

CREATE VIEW v_customers_transactions_1k AS SELECT customers.CustomerID, customers.Segment, customers.Currency, transactions_1k.TransactionID, transactions_1k.Date, transactions_1k.Time, transactions_1k.CustomerID AS transactions_1k_CustomerID, transactions_1k.GasStationID, transactions_1k.ProductID, transactions_1k.Amount, transactions_1k.Price FROM customers INNER JOIN transactions_1k ON customers.customerid = transactions_1k.customerid;

CREATE VIEW v_gasstations_transactions_1k_yearmonth AS SELECT gasstations.GasStationID, gasstations.ChainID, gasstations.Country, gasstations.Segment, transactions_1k.TransactionID, transactions_1k.Date, transactions_1k.Time, transactions_1k.CustomerID, transactions_1k.GasStationID AS transactions_1k_GasStationID, transactions_1k.ProductID, transactions_1k.Amount, transactions_1k.Price, yearmonth.CustomerID AS yearmonth_CustomerID, yearmonth.Date AS yearmonth_Date, yearmonth.Consumption FROM gasstations INNER JOIN transactions_1k ON gasstations.gasstationid = transactions_1k.gasstationid INNER JOIN yearmonth ON transactions_1k.customerid = yearmonth.customerid;

CREATE VIEW v_products_transactions_1k_yearmonth AS SELECT products.ProductID, products.Description, transactions_1k.TransactionID, transactions_1k.Date, transactions_1k.Time, transactions_1k.CustomerID, transactions_1k.GasStationID, transactions_1k.ProductID AS transactions_1k_ProductID, transactions_1k.Amount, transactions_1k.Price, yearmonth.CustomerID AS yearmonth_CustomerID, yearmonth.Date AS yearmonth_Date, yearmonth.Consumption FROM products INNER JOIN transactions_1k ON products.productid = transactions_1k.productid INNER JOIN yearmonth ON transactions_1k.customerid = yearmonth.customerid;

CREATE VIEW v_transactions_1k_yearmonth AS SELECT transactions_1k.TransactionID, transactions_1k.Date, transactions_1k.Time, transactions_1k.CustomerID, transactions_1k.GasStationID, transactions_1k.ProductID, transactions_1k.Amount, transactions_1k.Price, yearmonth.CustomerID AS yearmonth_CustomerID, yearmonth.Date AS yearmonth_Date, yearmonth.Consumption FROM transactions_1k INNER JOIN yearmonth ON transactions_1k.customerid = yearmonth.customerid;
